  `param_value` decimal(14,4) DEFAULT NULL COMMENT 'معامل الأثر إن لزم (مثال: مخصّص الصيانة للوحدة)',
  `unavailable_reason` varchar(200) DEFAULT NULL COMMENT 'سبب التعطيل — يظهر للمستخدم بدل الصمت',
