) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='D05 §6.1: خريطة تفريع الأثر — قواعد المروحة بياناتٍ لا كودًا';
