-- Dumping data for table `monthly_performance_downtime`
--

LOCK TABLES `monthly_performance_downtime` WRITE;
/*!40000 ALTER TABLE `monthly_performance_downtime` DISABLE KEYS */;
/*!40000 ALTER TABLE `monthly_performance_downtime` ENABLE KEYS */;
UNLOCK TABLES;

