--
-- Table structure for table `shift_patterns`
--

DROP TABLE IF EXISTS `shift_patterns`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `shift_patterns` (
  `pattern_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int(10) unsigned NOT NULL,
  `name_ar` varchar(120) NOT NULL,
  `shifts_per_day` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `base_hours` decimal(5,2) NOT NULL,
  `overtime_hours` decimal(5,2) NOT NULL DEFAULT 0.00,
  `crosses_midnight` tinyint(1) NOT NULL DEFAULT 0,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`pattern_id`),
  UNIQUE KEY `uq_sp_name` (`company_id`,`name_ar`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='WRK-01 §2: أنماط الورديات — قاموس يُضاف إليه بقرار، والمواعيد معرَّفة لا مثبَّتة في الكود';
/*!40101 SET character_set_client = @saved_cs_client */;

